 const save=async e=>{e.preventDefault();try{setError('');await saveEmployee({...(editing?{id:editing}:{}),name:form.name,email:form.email,city:form.city,salary:Number(form.salary),project:{id:Number(form.projectId)}});reset();load()}catch(e){setError(e.message)}};
 const edit=e=>{setEditing(e.id);setForm({name:e.name,email:e.email,city:e.city,salary:e.salary,projectId:e.project?.id||''})};
 const remove=async id=>{if(confirm('Delete this employee?'))try{await deleteEmployee(id);load()}catch(e){setError(e.message)}};
