function ManagerRecruitment(){const[apps,setApps]=useState([]),[error,setError]=useState(''),[rejecting,setRejecting]=useState(null),[queueFilter,setQueueFilter]=useState('NEW');const load=()=>getApplications().then(setApps).catch(e=>setError(e.message));useEffect(()=>{load()},[]);const approve=async a=>{try{await managerDecision(a.id,'MANAGER_APPROVED_REVIEW','');load()}catch(e){setError(e.message)}};const reject=async comment=>{try{await managerDecision(rejecting.id,'MANAGER_REJECTED',comment);setRejecting(null);load()}catch(e){setError(e.message)}};const complete=async a=>{try{await managerL1Complete(a.id);load()}catch(e){setError(e.message)}};const addComment=async a=>{setRejecting({type:'managerComment',id:a.id,application:a})};const saveComment=async comment=>{try{await managerComment(rejecting.id,comment);setRejecting(null);load()}catch(e){setError(e.message)}};const queue=apps.filter(a=>queueFilter==='NEW'?activeStatuses.includes(a.status):queueFilter==='REJECTED'?(a.status==='MANAGER_REJECTED'||a.status==='ADMIN_REJECTED'):(activeStatuses.includes(a.status)||a.status==='MANAGER_REJECTED'||a.status==='ADMIN_REJECTED'));return <><div className="panel"><div className="panel-head"><div><h2>Manager Recruitment Queue</h2><p className="hint">Use the queue filter to switch between new applications and rejected applications.</p></div><button className="refresh" onClick={load}>Refresh</button></div>{error&&<div className="error">{error}</div>}<div className="queue-filter"><label>Recruitment Queue <select value={queueFilter} onChange={e=>setQueueFilter(e.target.value)}><option value="NEW">New Applications</option><option value="REJECTED">Rejected Applications</option><option value="ALL">All Applications</option></select></label></div><div className="process-strip">{timeline.map(([s,l,t],i)=><div className="process-step" key={s}><span>{i+1}</span><b>{l}</b><small>{t}</small></div>)}</div><div className="table-scroll"><table><thead><tr><th>Application</th><th>Candidate</th><th>Job</th><th>Resume</th><th>Candidate Comment</th><th>Manager Comment</th><th>Status</th><th>Action</th></tr></thead><tbody>{queue.map(a=><tr key={a.id}><td><b>{a.applicationCode||a.id}</b></td><td>{a.candidateName}<small>{a.email}</small></td><td>{a.projectName||a.appliedRole}</td><td>{a.resumeFileName?<a href={`/api/applications/${a.id}/resume`} target="_blank" rel="noreferrer">View Resume</a>:'—'}</td><td className="wrap-cell">{a.comment||'—'}</td><td className="wrap-cell">{a.managerComment||'—'}</td><td>{badge(a.status)}{a.rejectionComment&&<small className="rejectnote">Admin/Manager reason: {a.rejectionComment}</small>}</td><td>{a.status==='PENDING'&&<><button className="success" onClick={()=>approve(a)}>Approved - Review</button> <button className="danger" onClick={()=>setRejecting({type:'managerReject',id:a.id,application:a})}>Reject</button></>}{a.status==='ADMIN_L1_REVIEW'&&<button className="primary smallbtn" onClick={()=>complete(a)}>L1 Completed → Approve</button>}{a.status==='L1_COMPLETED_MANAGER_APPROVED'&&<span className="hint">Waiting for Admin final approval</span>}{a.status==='ADMIN_REJECTED'&&<button className="refresh" onClick={()=>addComment(a)}>Add / Edit Comment</button>}</td></tr>)}</tbody></table></div>{!queue.length&&<div className="empty">No applications in the manager queue.</div>}</div>{rejecting&&rejecting.type==='managerReject'&&<DecisionModal title="Reject application" description="The rejection reason is required and will be shown to the candidate." confirmText="Reject Application" onConfirm={reject} onClose={()=>setRejecting(null)}/>} {rejecting&&rejecting.type==='managerComment'&&<DecisionModal title="Hiring Manager Comment" description="This comment is optional. The Admin rejection reason remains unchanged." required={false} initial={rejecting.application.managerComment||''} confirmText="Save Comment" onConfirm={saveComment} onClose={()=>setRejecting(null)}/>}</>}

function AdminRecruitment(){const[apps,setApps]=useState([]),[error,setError]=useState(''),[rejecting,setRejecting]=useState(null);const load=()=>getApplications().then(setApps).catch(e=>setError(e.message));useEffect(()=>{load()},[]);const sendL1=async a=>{try{await adminDecision(a.id,'ADMIN_L1_REVIEW','');load()}catch(e){setError(e.message)}};const reject=async comment=>{try{await adminDecision(rejecting.id,'ADMIN_REJECTED',comment);setRejecting(null);load()}catch(e){setError(e.message)}};const finalApprove=async a=>{try{await adminFinalApprove(a.id);load()}catch(e){setError(e.message)}};const queue=apps.filter(a=>activeStatuses.includes(a.status));return <><div className="panel"><div className="panel-head"><div><h2>Admin Application Review</h2><p className="hint">Manager review → Admin review → L1 interview → Manager approval → Admin final approval.</p></div><button className="refresh" onClick={load}>Refresh</button></div>{error&&<div className="error">{error}</div>}<div className="process-strip">{timeline.map(([s,l,t],i)=><div className="process-step" key={s}><span>{i+1}</span><b>{l}</b><small>{t}</small></div>)}</div><div className="table-scroll"><table><thead><tr><th>Application</th><th>Candidate</th><th>Job</th><th>Resume</th><th>Status</th><th>Comments</th><th>Action</th></tr></thead><tbody>{queue.map(a=><tr key={a.id}><td><b>{a.applicationCode||a.id}</b></td><td>{a.candidateName}<small>{a.email}</small></td><td>{a.projectName||a.appliedRole}</td><td>{a.resumeFileName?<a href={`/api/applications/${a.id}/resume`} target="_blank" rel="noreferrer">View Resume</a>:'—'}</td><td>{badge(a.status)}</td><td className="wrap-cell">{a.rejectionComment||a.comment||'—'}</td><td>{a.status==='MANAGER_APPROVED_REVIEW'&&<><button className="primary smallbtn" onClick={()=>sendL1(a)}>L1 Interview Review</button> <button className="danger" onClick={()=>setRejecting(a)}>Reject</button></>}{a.status==='ADMIN_L1_REVIEW'&&<button className="danger" onClick={()=>setRejecting(a)}>Reject</button>}{a.status==='L1_COMPLETED_MANAGER_APPROVED'&&<><button className="success" onClick={()=>finalApprove(a)}>Final Approve</button> <button className="danger" onClick={()=>setRejecting(a)}>Reject</button></>}{a.status==='PENDING'&&<span className="hint">Waiting for Manager</span>}</td></tr>)}</tbody></table></div>{!queue.length&&<div className="empty">No applications awaiting Admin action.</div>}</div>{rejecting&&<DecisionModal title="Admin Reject Application" description="Enter the rejection reason. The application will remain visible to the Hiring Manager and the candidate." confirmText="Reject Application" onConfirm={reject} onClose={()=>setRejecting(null)}/>}</>}

function downloadCandidateReport(a){
 const process=timeline.map(([s,label,text])=>{const idx=timeline.findIndex(x=>x[0]===s);const rejected=a.status==='MANAGER_REJECTED'||a.status==='ADMIN_REJECTED';const rejectionIndex=a.status==='MANAGER_REJECTED'?0:a.status==='ADMIN_REJECTED'?1:-1;let state=rejected?(idx<rejectionIndex?'Completed':idx===rejectionIndex?'Rejected':'Not reached'):(timeline.findIndex(x=>x[0]===a.status)>=idx?'Completed':'Pending');if(a.status==='SELECTED')state='Completed';return `<tr><td>${label}</td><td>${text}</td><td>${state}</td></tr>`}).join('');
 const esc=v=>String(v??'—').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
 const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(a.applicationCode||a.id)} Candidate Report</title><style>body{font-family:Arial,sans-serif;color:#172033;background:#f6f8ff;padding:32px}main{max-width:900px;margin:auto;background:#fff;border:1px solid #e4e7f0;border-radius:18px;padding:28px;box-shadow:0 10px 30px #1d2a4a12}h1{margin:0 0 6px;color:#4338ca}.muted{color:#667085}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.item{padding:12px;background:#f7f8ff;border-radius:10px}.item b{display:block;font-size:11px;color:#667085;margin-bottom:4px}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{border:1px solid #e4e7f0;padding:10px;text-align:left}th{background:#eef2ff}.reason{padding:14px;background:#fff5f5;border:1px solid #fecaca;border-radius:10px;margin-top:16px}</style></head><body><main><h1>Candidate Recruitment Report</h1><div class="muted">Application ${esc(a.applicationCode||a.id)} · Generated ${esc(new Date().toLocaleString())}</div><div class="grid"><div class="item"><b>Candidate</b>${esc(a.candidateName)}</div><div class="item"><b>Job / Project</b>${esc(a.projectName||a.appliedRole)}</div><div class="item"><b>Email</b>${esc(a.email)}</div><div class="item"><b>Phone</b>${esc(a.phone)}</div><div class="item"><b>Skills</b>${esc(a.skills)}</div><div class="item"><b>Status</b>${esc(statusText(a.status))}</div><div class="item"><b>Applied At</b>${esc(a.appliedAt?new Date(a.appliedAt).toLocaleString():'—')}</div><div class="item"><b>Resume</b>${esc(a.resumeFileName||'Not provided')}</div></div>${a.comment?`<div class="item"><b>Candidate Comment</b>${esc(a.comment)}</div>`:''}${a.managerComment?`<div class="item" style="margin-top:12px"><b>Manager Comment</b>${esc(a.managerComment)}</div>`:''}${a.rejectionComment?`<div class="reason"><b>Rejection Reason</b><br>${esc(a.rejectionComment)}</div>`:''}<h2>Recruitment Process</h2><table><thead><tr><th>Level</th><th>Stage</th><th>Result</th></tr></thead><tbody>${process}</tbody></table></main></body></html>`;
 const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${(a.applicationCode||'candidate-report').replace(/[^a-z0-9_-]/gi,'_')}-report.html`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);
}

function OutcomeEmployees({role,type}){const[apps,setApps]=useState([]),[error,setError]=useState(''),[search,setSearch]=useState('');const load=()=>getApplications().then(setApps).catch(e=>setError(e.message));useEffect(()=>{load()},[]);const list=apps.filter(a=>type==='selected'?a.status==='SELECTED':rejectedStatuses.includes(a.status));const filtered=list.filter(a=>{const q=search.trim().toLowerCase();if(!q)return true;return [a.applicationCode,a.candidateName,a.email,a.phone,a.projectName,a.appliedRole,a.status].some(v=>String(v||'').toLowerCase().includes(q))});return <div className="panel"><div className="panel-head"><div><h2>{type==='selected'?'Selected Employees':'Rejected Employees'}</h2><p className="hint">{role==='MANAGER'?'Hiring Manager view':'Administrator view'} · Search candidates and download their recruitment process report.</p></div><button className="refresh" onClick={load}>Refresh</button></div>{error&&<div className="error">{error}</div>}<div className="outcome-toolbar"><input className="search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="🔎 Search candidate, application, email or project…"/><span className="outcome-count">{filtered.length} result{filtered.length===1?'':'s'}</span></div><div className="outcome-grid">{filtered.map(a=><div className="outcome-card" key={a.id}><div className="outcome-top"><b>{a.applicationCode||a.id}</b>{badge(a.status)}</div><h3>{a.candidateName}</h3><p>{a.projectName||a.appliedRole}</p><small>{a.email} · {a.phone}</small><small>Skills: {a.skills}</small>{a.rejectionComment&&<p className="rejectnote"><b>Rejection reason:</b> {a.rejectionComment}</p>}{a.managerComment&&<p><b>Manager comment:</b> {a.managerComment}</p>}{a.resumeFileName&&<p><b>Resume:</b> <a href={`/api/applications/${a.id}/resume`} target="_blank" rel="noreferrer">{a.resumeFileName}</a></p>}<div className="outcome-actions"><button className="primary" type="button" onClick={()=>downloadCandidateReport(a)}>⬇ Download Process Report</button></div><ApplicationTimeline status={a.status}/></div>)}</div>{!filtered.length&&<div className="empty">No {type} applications match your search.</div>}</div>}

function ApplicationTimeline({status}){const rejected=status==='MANAGER_REJECTED'||status==='ADMIN_REJECTED';const rejectionIndex=status==='MANAGER_REJECTED'?0:status==='ADMIN_REJECTED'?1:-1;const current=timeline.findIndex(x=>x[0]===status);return <div className="timeline"><div className="timeline-title">Selection process</div>{timeline.map(([s,label,text],i)=>{const isRejectedStage=rejected&&i===rejectionIndex;const done=!rejected&&current>=i;const isCurrent=!rejected&&s===status;const notReached=rejected&&i>rejectionIndex;return <div className={'timeline-item '+(done?'done ':'')+(isCurrent?'current ':'')+(isRejectedStage?'stage-rejected ':'')} key={s}><span className="timeline-dot">{isRejectedStage?'!':done?'✓':i+1}</span><div><b>{label} · {text}</b><small>{isRejectedStage?'Rejected':notReached?'Not reached':isCurrent?'Current status':done?'Completed':'Pending'}</small></div></div>})}{rejected&&<div className="timeline-item rejected-line"><span className="timeline-dot">!</span><div><b>{status==='ADMIN_REJECTED'?'Rejected by Admin':'Rejected by Manager'}</b></div></div>}</div>}

function CandidatePortal({user,section,onNavigate}){
 const [projects,setProjects]=useState([]),[apps,setApps]=useState([]),[query,setQuery]=useState(''),[showForm,setShowForm]=useState(false),[form,setForm]=useState({candidateName:user.name||'',candidateUsername:user.username,email:user.username==='candidate'?'candidate@example.com':user.username,phone:'',skills:'',appliedRole:'',projectId:'',comment:''}),[error,setError]=useState(''),[message,setMessage]=useState(''),[loading,setLoading]=useState(false),[selectedJob,setSelectedJob]=useState(null),[resume,setResume]=useState(null);
 const load=async()=>{try{setError('');const [p,a]=await Promise.all([getProjects(),getCandidateApplicationsByUsername(user.username)]);setProjects(p);setApps(a)}catch(e){setError(e.message)}};
 useEffect(()=>{load()},[user.username]);
 const jobs=projects.filter(p=>(p.name||'').toLowerCase().includes(query.toLowerCase()));
 const isRejected=s=>rejectedStatuses.includes(s);
 const appForProject=id=>{const matches=apps.filter(a=>Number(a.projectId)===Number(id));return matches.find(a=>!isRejected(a.status))||matches[0]||null};
 const skillMatch=(candidate,required)=>{if(!required||!required.trim())return true;const c=new Set((candidate||'').toLowerCase().split(/[,;|]/).map(x=>x.trim()).filter(Boolean));return required.toLowerCase().split(/[,;|]/).map(x=>x.trim()).filter(Boolean).some(x=>c.has(x))};
 const openApply=p=>{setSelectedJob(p);setForm(f=>({...f,projectId:p.id,appliedRole:p.name}));setResume(null);setShowForm(true);setError('');setMessage('')};
 const submit=async e=>{e.preventDefault();try{setLoading(true);setError('');const clean={...form,candidateName:form.candidateName.trim(),candidateUsername:user.username,email:form.email.trim(),phone:form.phone.trim(),skills:form.skills.trim(),appliedRole:form.appliedRole.trim(),comment:form.comment.trim()};if(!clean.candidateName||!clean.email||!clean.phone||!clean.skills||!clean.appliedRole||!clean.projectId||!clean.comment)throw Error('Please complete all required application details.');if(!resume)throw Error('Please select your resume. PDF, DOC or DOCX up to 10 MB is supported.');if(!skillMatch(clean.skills,selectedJob?.skills))throw Error(`Your skills do not match this job. Required skills: ${selectedJob?.skills||'Not specified'}`);const created=await applyCandidate(clean);await uploadResume(created.id,resume);setShowForm(false);setSelectedJob(null);setResume(null);setMessage('Application submitted successfully. Level 1 · Manager Review is now in progress.');setForm(f=>({...f,phone:'',skills:'',comment:''}));await load()}catch(e){setError(e.message)}finally{setLoading(false)}};
 const jobsScreen=<>
   <div className="panel hero"><div className="panel-head"><div><h2>My Jobs</h2><p className="hint">Browse available jobs and apply. Rejected applications can be submitted again.</p></div><span className="pill">Candidate Portal</span></div><input className="search" placeholder="🔎 Search jobs…" value={query} onChange={e=>setQuery(e.target.value)}/><div className="jobs">{jobs.map(p=>{const a=appForProject(p.id),rejected=a&&isRejected(a.status);return <div className="job" key={p.id}><div><b>{p.name}</b><small>Budget {money(p.budget)} · {money(p.remaining)} remaining</small><small>Required skills: {p.skills||'Any skill'}</small><small>{p.jobRole||'Role'} · {p.location||'Location'} · {p.experience||'Experience'}</small>{p.jobDescription&&<small>{p.jobDescription}</small>}{a&&<small className="job-status">{statusText(a.status)}</small>}{rejected&&<small className="job-status">This job is available again — you can re-apply.</small>}</div>{a?<button className="primary" onClick={()=>openApply(p)}>{rejected?'Apply Again':'Apply Again'}</button>:<button className="primary" onClick={()=>openApply(p)}>Apply Now</button>}</div>})}</div>{!jobs.length&&<div className="empty">No jobs match your search.</div>}</div>
   {showForm&&<div className="panel application-form"><div className="panel-head"><div><h2>Apply for {selectedJob?.name}</h2><p className="hint">Please provide the following details. All fields are required.</p></div><button className="refresh" type="button" onClick={()=>setShowForm(false)}>✕</button></div><form onSubmit={submit} className="form-grid"><label>Candidate Name *<input required value={form.candidateName} onChange={e=>setForm({...form,candidateName:e.target.value})}/></label><label>Email *<input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Phone Number *<input required value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} placeholder="10-digit mobile number"/></label><label>Skills *<input required value={form.skills} onChange={e=>setForm({...form,skills:e.target.value})} placeholder="Java, Spring Boot, React, SQL"/></label><label>Applied Role *<input required value={form.appliedRole} onChange={e=>setForm({...form,appliedRole:e.target.value})}/></label><label>Job *<select required value={form.projectId} onChange={e=>{const p=projects.find(x=>Number(x.id)===Number(e.target.value));setForm({...form,projectId:e.target.value,appliedRole:p?.name||form.appliedRole})}}><option value="">Select job</option>{projects.filter(p=>{const a=appForProject(p.id);return !a||isRejected(a.status)||Number(p.id)===Number(form.projectId)}).map(p=><option key={p.id} value={p.id}>{p.name}{isRejected(appForProject(p.id)?.status)?' · Apply Again':''}</option>)}</select></label><label className="full-field">Resume *<input required type="file" accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={e=>setResume(e.target.files?.[0]||null)}/><small>PDF, DOC or DOCX · maximum 10 MB</small></label><div className="full-field hint">Required skills: <b>{selectedJob?.skills||'Any skill'}</b>{form.skills.trim()&&!skillMatch(form.skills,selectedJob?.skills)&&<span className="rejectnote"> · Your entered skills do not match this job.</span>}</div><label className="full-field">Why should we consider you? *<textarea required rows="5" value={form.comment} onChange={e=>setForm({...form,comment:e.target.value})} placeholder="Tell the Manager about your experience, strengths and fit for this role."/></label>{error&&<div className="error full-field">{error}</div>}<div className="full-field form-actions"><button className="primary" disabled={loading}>{loading?'Submitting…':'Submit Application'}</button><button type="button" className="refresh" onClick={()=>setShowForm(false)}>Cancel</button></div></form></div>}
   {message&&<div className="success-msg">{message}</div>}{error&&!showForm&&<div className="error">{error}</div>}
 </>;
 const applicationsScreen=<div className="panel" id="my-applications"><div className="panel-head"><div><h2>My Applications</h2><p className="hint">Track every application and its current recruitment level.</p></div><button className="refresh" onClick={load}>Refresh</button></div>{apps.length?apps.map(a=><div className="application" key={a.id}><div className="application-main"><div><b>{a.applicationCode||a.id} · {a.projectName||a.appliedRole}</b><small>{a.candidateName} · {a.email} · {a.phone}</small><small>Skills: {a.skills}</small><small>Applied {new Date(a.appliedAt).toLocaleString()}</small><small className="application-level">Current level: {statusText(a.status)}</small>{a.comment&&<small>Comment: {a.comment}</small>}{a.rejectionComment&&<small className="rejectnote">Rejection reason: {a.rejectionComment}</small>}{a.managerComment&&<small>Hiring Manager comment: {a.managerComment}</small>}{a.resumeFileName&&<small>Resume: {a.resumeFileName}</small>}</div><div>{badge(a.status)}</div></div><ApplicationTimeline status={a.status}/></div>):<div className="empty">No applications yet. Go to My Jobs to apply for a position.</div>}</div>;
 return section==='myjobs'?jobsScreen:applicationsScreen;
}

createRoot(document.getElementById('root')).render(<App/>);
